import { piiSignals } from '../publicationSafety'

export type PromotionKind = 'completed' | 'new_room' | 'deadline' | 'weekly'
export type PromotionCandidate = {
  // Stable event identity, generated by the trusted server adapter (never client input).
  id: string
  kind: PromotionKind
  createdAt: string
  expiresAt: string
  snapshotAt: string
  public: boolean
  hidden: boolean
  deleted: boolean
  pendingReport: boolean
  creatorExcluded: boolean
  reviewed: boolean
  piiClear: boolean
  title: string
  targetId: string
  seatsAvailable?: number
  deadlineAt?: string
  weeklyCounts?: { rooms: number; works: number; participants: number }
}
export type PromotionHistory = {
  eventId: string
  contentKey: string
  kind: PromotionKind
  dueAt: string
  state: 'reserved' | 'sent' | 'uncertain' | 'cancelled'
}
export type PlannedPromotion = {
  eventId: string; contentKey: string; kind: PromotionKind; dueAt: string; text: string
}
const priorities: Record<PromotionKind, number> = { completed: 0, new_room: 1, deadline: 2, weekly: 3 }
const hour = 3_600_000
const jst = 9 * hour
const instant = (value: string) => /(?:Z|[+-]\d{2}:\d{2})$/.test(value) ? Date.parse(value) : NaN
const day = (ms: number) => new Date(ms + jst).toISOString().slice(0, 10)
const key = (c: PromotionCandidate) => c.kind + ':' + c.targetId

function safe(c: PromotionCandidate, now: number, due: number) {
  if (!(Object.hasOwn(priorities, c.kind)) || !/^[a-zA-Z0-9_-]{1,100}$/.test(c.id) ||
      !/^[a-zA-Z0-9_-]{1,100}$/.test(c.targetId)) return false
  if (c.public !== true || c.hidden !== false || c.deleted !== false ||
      c.pendingReport !== false || c.creatorExcluded !== false ||
      c.reviewed !== true || c.piiClear !== true) return false
  const created = instant(c.createdAt), snapshot = instant(c.snapshotAt), expires = instant(c.expiresAt)
  if (![created, snapshot, expires].every(Number.isFinite) ||
      created > now || snapshot > now || now - snapshot > 5 * 60_000 || expires <= due) return false
  // Review flags complement detection; regex alone cannot certify absence of PII.
  if (typeof c.title !== 'string' || !c.title.trim() || piiSignals(c.title).length ||
      /https?:|www\.|[\u0000-\u001f\u007f\u202a-\u202e\u2066-\u2069]/i.test(c.title)) return false
  if (c.kind === 'new_room' || c.kind === 'deadline') {
    if (!Number.isSafeInteger(c.seatsAvailable) || c.seatsAvailable! <= 0) return false
    const deadline = instant(c.deadlineAt ?? '')
    if (!Number.isFinite(deadline) || deadline <= due) return false
    if (c.kind === 'deadline' && deadline - due > 24 * hour) return false
  }
  if (c.kind === 'weekly') {
    if (new Date(due + jst).getUTCDay() !== 0 || !c.weeklyCounts ||
        !Object.values(c.weeklyCounts).every(n => Number.isSafeInteger(n) && n >= 0 && n <= 999999)) return false
    if (!['rooms', 'works', 'participants'].every(k => k in c.weeklyCounts!)) return false
  }
  return true
}
function render(c: PromotionCandidate) {
  const title = Array.from(c.title.trim()).slice(0, 32).join('')
  const base = 'https://minnade-tsukuru.vercel.app'
  if (c.kind === 'weekly') {
    const counts = c.weeklyCounts!
    return '今週のみんつく\n新しいルーム ' + counts.rooms + '件／完成作品 ' + counts.works +
      '件／参加者 ' + counts.participants + '人\n' + base + '/works\n#みんつく #共同創作'
  }
  const heading = { completed: '作品が完成しました', new_room: '新しい制作ルーム', deadline: '締切が近づいています' }[c.kind]
  const path = c.kind === 'completed' ? '/works/' : '/rooms/'
  return heading + '\n「' + title + '」\n' + base + path + c.targetId + '\n#みんつく #共同創作'
}

/**
 * Pure dry-run only. No persistence, network, reservation or publishing.
 * History must include ALL reserved/sent/uncertain records, not just this day.
 * A future sender must atomically reserve, revalidate source at send-time, and
 * never automatically retry an ambiguous result. This plan is NOT authorization.
 */
export function planPromotions(candidates: PromotionCandidate[], history: PromotionHistory[], nowIso: string): PlannedPromotion[] {
  const now = instant(nowIso)
  if (!Number.isFinite(now)) throw new Error('INVALID_NOW')
  const active = history.filter(h => h.state !== 'cancelled')
  // Incomplete history must block planning, never silently loosen the daily cap.
  if (active.some(h => !Number.isFinite(instant(h.dueAt)) ||
      !['reserved','sent','uncertain'].includes(h.state) || !(Object.hasOwn(priorities, h.kind)) || !h.eventId || !h.contentKey)) {
    throw new Error('INVALID_HISTORY')
  }
  const today = day(now)
  const usedToday = active.filter(h => day(instant(h.dueAt)) === today)
  if (usedToday.length >= 2) return []
  const slots = ['12:00:00', '20:30:00'].map(t => Date.parse(today + 'T' + t + '+09:00'))
    .filter(t => t >= now && !usedToday.some(h => instant(h.dueAt) === t))
  if (!slots.length) return []
  const seenEvents = new Set(active.map(h => h.eventId))
  const seenContent = new Set(active.map(h => h.contentKey))
  let newRooms = usedToday.filter(h => h.kind === 'new_room').length
  const sorted = [...candidates].filter(c => Object.hasOwn(priorities, c.kind))
    .sort((a,b) => priorities[a.kind] - priorities[b.kind] ||
      instant(a.createdAt) - instant(b.createdAt) || a.id.localeCompare(b.id))
  const result: PlannedPromotion[] = []
  // One eligible item goes in the evening. Two eligible items use noon + evening.
  const eligible = (c: PromotionCandidate, t: number) =>
    !seenEvents.has(c.id) && !seenContent.has(key(c)) &&
    (c.kind !== 'new_room' || newRooms === 0) && safe(c, now, t)
  const evening = slots[slots.length - 1]
  const first = sorted.find(c => eligible(c, evening))
  if (!first) return []
  const add = (c: PromotionCandidate, t: number) => {
    result.push({eventId:c.id,contentKey:key(c),kind:c.kind,dueAt:new Date(t).toISOString(),text:render(c)})
    seenEvents.add(c.id); seenContent.add(key(c))
    if (c.kind === 'new_room') newRooms++
  }
  // Prefer higher priority first. Require the noon candidate to still be safe at noon.
  if (slots.length === 2 && usedToday.length === 0 && safe(first,now,slots[0])) {
    const second = sorted.find(c => c.id !== first.id && key(c) !== key(first) &&
      !(first.kind === 'new_room' && c.kind === 'new_room') && eligible(c,evening))
    if (second) { add(first,slots[0]); add(second,evening); return result }
  }
  add(first,evening)
  return result
}


/** Revalidate the exact queued body against a newly read authoritative snapshot. */
export function validateQueuedPromotion(c: PromotionCandidate | undefined, p: PlannedPromotion, nowIso: string): boolean {
  const now = instant(nowIso), due = instant(p.dueAt)
  return !!c && Number.isFinite(now) && Number.isFinite(due) && due > now &&
    c.id === p.eventId && c.kind === p.kind && key(c) === p.contentKey &&
    safe(c, now, due) && render(c) === p.text
}

export const BUFFER_TEST_BODY = '【TEST】みんつく Buffer/X連携の動作確認です。\n作品の公開・参加募集ではありません。\nhttps://x.com/minnade_tsukuru\n#みんつく #連携テスト'

export const BUFFER_CANCEL_TEST_BODY = '【TEST】みんつく Buffer/X連携の予約取消テストです。\n作品の公開・参加募集ではありません。\nhttps://x.com/minnade_tsukuru\n#みんつく #取消検証'

/** Only the separately authorized TEST work can use a short canary time slot. */
export function validateTestCanary(c: PromotionCandidate | undefined, p: PlannedPromotion, nowIso: string): boolean {
  const now = instant(nowIso), due = instant(p.dueAt)
  return !!c && c.kind === 'completed' && c.title.startsWith('TEST Buffer') &&
    c.id === p.eventId && key(c) === p.contentKey && p.kind === c.kind &&
    [BUFFER_TEST_BODY, BUFFER_CANCEL_TEST_BODY].includes(p.text) && Number.isFinite(now) && Number.isFinite(due) &&
    due > now + 60_000 && due <= now + 15 * 60_000 && safe(c, now, due)
}

/** The same safety and rendering checks, also valid after the scheduled time. */
export function validateScheduledPromotion(c: PromotionCandidate | undefined, p: PlannedPromotion, nowIso: string): boolean {
  const now = instant(nowIso), due = instant(p.dueAt)
  return !!c && Number.isFinite(now) && Number.isFinite(due) &&
    c.id === p.eventId && c.kind === p.kind && key(c) === p.contentKey &&
    safe(c, now, Math.max(due, now + 1)) && render(c) === p.text
}

/** Used only by the local staging canary adapter, never by the production cron. */
export function validateScheduledTestCanary(c: PromotionCandidate | undefined, p: PlannedPromotion, nowIso: string): boolean {
 const now = instant(nowIso), due = instant(p.dueAt)
 return !!c && c.kind === 'completed' && c.title.startsWith('TEST Buffer') && c.id === p.eventId && key(c) === p.contentKey &&
  [BUFFER_TEST_BODY, BUFFER_CANCEL_TEST_BODY].includes(p.text) && Number.isFinite(now) && Number.isFinite(due) &&
  safe(c, now, Math.max(now + 1, due))
}
